using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.OrderByDescending(s => s.CreatedAt).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == customerEmail)
            .OrderByDescending(s => s.CreatedAt)
            .ToListAsync();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = GenerateTrackingNumber();
        shipment.CreatedAt = DateTime.UtcNow;
        shipment.Status = ShipmentStatus.Pending;
        shipment.EstimatedDelivery = DateTime.UtcNow.AddDays(Random.Shared.Next(3, 10));

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException("Shipment not found");

        shipment.Status = status;
        if (status == ShipmentStatus.Delivered)
            shipment.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return shipment;
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Controllers;

[ApiController]
[Route("api/shipments")]
[Authorize]
public class ShipmentsController(IShipmentService shipmentService) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<List<Shipment>>> GetAll()
    {
        var shipments = await shipmentService.GetAllShipmentsAsync();
        return Ok(shipments);
    }

    [HttpGet("track/{trackingNumber}")]
    [AllowAnonymous]
    public async Task<ActionResult<Shipment>> GetByTracking(string trackingNumber)
    {
        var shipment = await shipmentService.GetShipmentByTrackingNumberAsync(trackingNumber);
        if (shipment is null) return NotFound();
        return Ok(shipment);
    }

    [HttpGet("customer/{email}")]
    public async Task<ActionResult<List<Shipment>>> GetByCustomer(string email)
    {
        var shipments = await shipmentService.GetShipmentsByCustomerAsync(email);
        return Ok(shipments);
    }

    [HttpPost]
    public async Task<ActionResult<Shipment>> Create(Shipment shipment)
    {
        var created = await shipmentService.CreateShipmentAsync(shipment);
        return CreatedAtAction(nameof(GetByTracking), new { trackingNumber = created.TrackingNumber }, created);
    }

    [HttpPut("{id}/status")]
    public async Task<ActionResult<Shipment>> UpdateStatus(int id, [FromBody] ShipmentStatus status)
    {
        var updated = await shipmentService.UpdateShipmentStatusAsync(id, status);
        return Ok(updated);
    }
}

