using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static void Initialize(ApplicationDbContext db)
    {
        if (db.Shipments.Any()) return;

        var shipments = new List<Shipment>
        {
            new()
            {
                TrackingNumber = "SHP-20260701-100001",
                Origin = "New York, USA",
                Destination = "London, UK",
                Status = ShipmentStatus.InTransit,
                CreatedAt = DateTime.UtcNow.AddDays(-3),
                EstimatedDelivery = DateTime.UtcNow.AddDays(4),
                CustomerEmail = "alice@example.com",
                Description = "Electronics - 2 boxes"
            },
            new()
            {
                TrackingNumber = "SHP-20260702-100002",
                Origin = "Tokyo, Japan",
                Destination = "Sydney, Australia",
                Status = ShipmentStatus.PickedUp,
                CreatedAt = DateTime.UtcNow.AddDays(-1),
                EstimatedDelivery = DateTime.UtcNow.AddDays(6),
                CustomerEmail = "bob@example.com",
                Description = "Auto parts - 1 pallet"
            },
            new()
            {
                TrackingNumber = "SHP-20260630-100003",
                Origin = "Berlin, Germany",
                Destination = "São Paulo, Brazil",
                Status = ShipmentStatus.OutForDelivery,
                CreatedAt = DateTime.UtcNow.AddDays(-7),
                EstimatedDelivery = DateTime.UtcNow,
                CustomerEmail = "carlos@example.com",
                Description = "Medical supplies - 5 boxes"
            },
            new()
            {
                TrackingNumber = "SHP-20260628-100004",
                Origin = "Shanghai, China",
                Destination = "Los Angeles, USA",
                Status = ShipmentStatus.Delivered,
                CreatedAt = DateTime.UtcNow.AddDays(-10),
                EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                ActualDelivery = DateTime.UtcNow.AddDays(-3),
                CustomerEmail = "diana@example.com",
                Description = "Textiles - 3 containers"
            },
            new()
            {
                TrackingNumber = "SHP-20260705-100005",
                Origin = "Mumbai, India",
                Destination = "Dubai, UAE",
                Status = ShipmentStatus.Delayed,
                CreatedAt = DateTime.UtcNow.AddDays(-2),
                EstimatedDelivery = DateTime.UtcNow.AddDays(3),
                CustomerEmail = "alice@example.com",
                Description = "Furniture - 2 pallets"
            }
        };

        db.Shipments.AddRange(shipments);
        db.SaveChanges();
    }
}

@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Shipments - Dispatch Board</PageTitle>

<h3>Dispatch Board</h3>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="LoadShipments">
            🔄 Refresh
        </button>
        <button class="btn btn-success ms-2" @onclick="() => showCreateForm = true">
            ➕ New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
            </div>
            <div class="mt-2">
                <button class="btn btn-primary btn-sm" @onclick="CreateShipment">Create</button>
                <button class="btn btn-secondary btn-sm ms-1" @onclick="() => showCreateForm = false">Cancel</button>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>@shipment.CustomerEmail</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                @onchange="e => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == shipment.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private Shipment newShipment = new();

    private IEnumerable<Shipment> FilteredShipments => shipments?
        .Where(s => string.IsNullOrEmpty(filterText) ||
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) ||
                    s.Status.ToString() == statusFilter)
        ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new();
        showCreateForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h3>Track Your Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260701-100001)"
                   @bind="trackingNumber" @onkeypress="HandleKeyPress" />
            <button class="btn btn-primary" @onclick="TrackShipment">
                🔍 Track
            </button>
        </div>
    </div>
</div>

@if (isLoading)
{
    <p><em>Searching...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}
else if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment: <code>@shipment.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>

                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>

                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>

                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <span class="fw-bold text-primary">@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</span>
                            }
                            else
                            {
                                <span class="text-muted">Not available</span>
                            }
                        </dd>

                        <dt>Actual Delivery</dt>
                        <dd>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <span class="text-success">✅ @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</span>
                            }
                            else
                            {
                                <span class="text-muted">In progress</span>
                            }
                        </dd>
                    </dl>
                </div>
            </div>

            <!-- Progress visualization -->
            <h6 class="mt-3">Shipment Progress</h6>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                     role="progressbar"
                     style="width: @GetProgressPercentage(shipment.Status)%"
                     aria-valuenow="@GetProgressPercentage(shipment.Status)"
                     aria-valuemin="0" aria-valuemax="100">
                    @shipment.Status
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private Shipment? shipment;
    private bool isLoading;
    private string? errorMessage;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (shipment is null)
                errorMessage = $"No shipment found with tracking number '{trackingNumber}'.";
        }
        catch
        {
            errorMessage = "Unable to retrieve shipment information. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyPress(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-primary"
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Components.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>My Shipments</PageTitle>

<h3>My Shipments</h3>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">You have no shipments yet.</div>
}
else
{
    <div class="row">
        @foreach (var shipment in shipments)
        {
            <div class="col-md-6 mb-3">
                <div class="card @(shipment.Status == ShipmentStatus.Delivered ? "border-success" : shipment.Status == ShipmentStatus.Delayed ? "border-danger" : "")">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@shipment.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="card-text">
                            <strong>@shipment.Origin</strong> → <strong>@shipment.Destination</strong>
                        </p>
                        <p class="card-text text-muted">@shipment.Description</p>
                        <div class="row">
                            <div class="col">
                                <small class="text-muted">Estimated Delivery</small><br />
                                <strong>@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</strong>
                            </div>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <div class="col">
                                    <small class="text-muted">Delivered On</small><br />
                                    <strong class="text-success">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</strong>
                                </div>
                            }
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Shipment>? shipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? "";
        if (!string.IsNullOrEmpty(email))
        {
            shipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
        }
        else
        {
            shipments = [];
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };
}

